INSERT INTO public.places (images_id,districts_id,"name",postal_code,map_link,description,created_at,updated_at,"type") VALUES
	 (2,2,'Golden Gate Bridge','94129','https://maps.app.goo.gl/GoldenGateBridge','The Golden Gate Bridge is a famous suspension bridge in San Francisco, known for its stunning views of the bay, architectural beauty, and historical significance.','2024-01-06 21:51:03.218','2024-01-07 07:58:09.656','Hotel'),
	 (3,3,'Grand Canyon National Park','86023','https://maps.app.goo.gl/GrandCanyonNP','Grand Canyon National Park in Arizona is a natural wonder characterized by its immense size, layered bands of colorful rocks, and the Colorado River winding through.','2024-01-06 21:51:03.218','2024-01-07 07:58:09.658','Shopping'),
	 (4,4,'Eiffel Tower','75007','https://maps.app.goo.gl/EiffelTower','The Eiffel Tower in Paris is an iconic symbol of France, offering panoramic views of the city, cultural significance, and stunning iron lattice architecture.','2024-01-06 21:51:03.218','2024-01-07 07:58:09.659','Hotel'),
	 (5,5,'Great Wall of China','100041','https://maps.app.goo.gl/GreatWallChina','The Great Wall of China is an ancient fortification, recognized as one of the most impressive architectural feats, spanning across historical Chinese borders.','2024-01-06 21:51:03.218','2024-01-07 07:58:09.660','Attraction'),
	 (6,1,'Times Square','10036','https://maps.app.goo.gl/TimesSquare','Times Square in New York City is a vibrant commercial hub, known for its bright billboards, Broadway theaters, shops, and lively atmosphere.','2024-01-06 21:51:03.218','2024-01-07 07:58:09.660','Attraction'),
	 (7,2,'Yosemite National Park','95389','https://maps.app.goo.gl/YosemiteNP','Yosemite National Park in California is famed for its granite cliffs, waterfalls like Yosemite Falls, diverse flora and fauna, and beautiful valleys.','2024-01-06 21:51:03.218','2024-01-07 07:58:09.661','Entertainment'),
	 (1,3,'The Louvre','75001','https://maps.app.goo.gl/TheLouvre','The Louvre Museum in Paris is a historic monument and one of the world''s largest art museums, housing thousands of works, including the Mona Lisa and Venus de Milo.','2024-01-06 21:51:03.218','2024-01-07 07:58:09.662','Cafe'),
	 (2,4,'Statue of Liberty','10004','https://maps.app.goo.gl/StatueOfLiberty','The Statue of Liberty in New York Harbor is a symbol of freedom and democracy, welcoming immigrants and visitors to the United States.','2024-01-06 21:51:03.218','2024-01-07 07:58:09.664','Museum'),
	 (1,1,'Central Park','10024','https://maps.app.goo.gl/CentralPark','Central Park is an iconic urban park in New York City, offering vast green spaces, walking paths, recreational facilities, and cultural landmarks.','2024-01-06 21:51:03.218','2024-01-07 07:58:09.647','Restaurant'),
	 (16,5,'Taj Mahal','282001','https://maps.app.goo.gl/TajMahal','The Taj Mahal in India is an exquisite white marble mausoleum, renowned for its architectural beauty, intricate craftsmanship, and romantic history.','2024-01-06 21:51:03.218','2024-01-07 08:16:31.077','Library');
INSERT INTO public.places (images_id,districts_id,"name",postal_code,map_link,description,created_at,updated_at,"type") VALUES
	 (15,12,'Futamatagawa Nichome Park','241-0821','https://maps.app.goo.gl/6p9kCSLSo754ddhM7','Like other reviewers, I took my child to see the Shinkansen.
